window.HJ_QURAN=[{"slug":"al-fatihah","number":1,"name":{"id":"Al-Fatihah","en":"Al-Fatihah"},"arabicName":"الْفَاتِحَة","meaning":{"id":"Pembukaan","en":"The Opening"},"ayahs":[{"n":1,"ar":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ","tr":"Bismillaahir-rahmaanir-rahiim","id":"Dengan nama Allah Yang Maha Pengasih, Maha Penyayang.","en":"In the name of Allah, the Most Gracious, the Most Merciful."},{"n":2,"ar":"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ","tr":"Alhamdu lillaahi rabbil-'aalamiin","id":"Segala puji bagi Allah, Tuhan seluruh alam.","en":"All praise is due to Allah, Lord of all the worlds."},{"n":3,"ar":"الرَّحْمَٰنِ الرَّحِيمِ","tr":"Ar-rahmaanir-rahiim","id":"Yang Maha Pengasih, Maha Penyayang.","en":"The Most Gracious, the Most Merciful."},{"n":4,"ar":"مَالِكِ يَوْمِ الدِّينِ","tr":"Maaliki yawmid-diin","id":"Pemilik hari pembalasan.","en":"Master of the Day of Judgement."},{"n":5,"ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","tr":"Iyyaaka na'budu wa iyyaaka nasta'iin","id":"Hanya kepada-Mu kami menyembah, dan hanya kepada-Mu kami memohon pertolongan.","en":"You alone we worship, and You alone we ask for help."},{"n":6,"ar":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","tr":"Ihdinas-siraatal-mustaqiim","id":"Tunjukilah kami jalan yang lurus.","en":"Guide us to the straight path."},{"n":7,"ar":"صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ","tr":"Siraatal-ladziina an'amta 'alayhim ghayril-maghdhuubi 'alayhim wa lad-dhaalliin","id":"(Yaitu) jalan orang-orang yang telah Engkau beri nikmat, bukan (jalan) mereka yang dimurkai, dan bukan (pula jalan) mereka yang sesat.","en":"The path of those upon whom You have bestowed favor — not of those who have earned anger, nor of those who go astray."}]},
{"slug":"al-ikhlas","number":112,"name":{"id":"Al-Ikhlas","en":"Al-Ikhlas"},"arabicName":"الْإِخْلَاص","meaning":{"id":"Memurnikan Keesaan Allah","en":"The Purity of Faith"},"ayahs":[{"n":1,"ar":"قُلْ هُوَ اللَّهُ أَحَدٌ","tr":"Qul huwallaahu ahad","id":"Katakanlah (Muhammad): \"Dialah Allah, Yang Maha Esa.\"","en":"Say: \"He is Allah, the One.\""},{"n":2,"ar":"اللَّهُ الصَّمَدُ","tr":"Allaahus-samad","id":"Allah tempat meminta segala sesuatu.","en":"Allah, the Eternal, on Whom all depend."},{"n":3,"ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","tr":"Lam yalid wa lam yuulad","id":"Dia tidak beranak dan tidak pula diperanakkan.","en":"He neither begets nor is born."},{"n":4,"ar":"وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","tr":"Wa lam yakul-lahu kufuwan ahad","id":"Dan tidak ada sesuatu yang setara dengan Dia.","en":"And there is none comparable to Him."}]},
{"slug":"an-nas","number":114,"name":{"id":"An-Nas","en":"An-Nas"},"arabicName":"النَّاس","meaning":{"id":"Manusia","en":"Mankind"},"ayahs":[{"n":1,"ar":"قُلْ أَعُوذُ بِرَبِّ النَّاسِ","tr":"Qul a'uudzu birabbin-naas","id":"Katakanlah: \"Aku berlindung kepada Tuhannya manusia,\"","en":"Say: \"I seek refuge with the Lord of mankind,\""},{"n":2,"ar":"مَلِكِ النَّاسِ","tr":"Malikin-naas","id":"Raja manusia,","en":"The King of mankind,"},{"n":3,"ar":"إِلَٰهِ النَّاسِ","tr":"Ilaahin-naas","id":"sembahan manusia,","en":"The God of mankind,"},{"n":4,"ar":"مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ","tr":"Min syarril-waswaasil-khannaas","id":"dari kejahatan (bisikan) setan yang bersembunyi,","en":"from the evil of the whisperer who hides,"},{"n":5,"ar":"الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ","tr":"Alladzii yuwaswisu fii suduurin-naas","id":"yang membisikkan (kejahatan) ke dalam dada manusia,","en":"who whispers into the breasts of mankind,"},{"n":6,"ar":"مِنَ الْجِنَّةِ وَالنَّاسِ","tr":"Minal-jinnati wan-naas","id":"dari (golongan) jin dan manusia.","en":"from among the jinn and mankind."}]},
{"slug":"al-falaq","number":113,"name":{"id":"Al-Falaq","en":"Al-Falaq"},"arabicName":"الْفَلَق","meaning":{"id":"Waktu Subuh","en":"The Daybreak"},"ayahs":[{"n":1,"ar":"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ","tr":"Qul a'uudzu birabbil-falaq","id":"Katakanlah: \"Aku berlindung kepada Tuhan yang menguasai waktu subuh,","en":"Say: \"I seek refuge with the Lord of the daybreak,"},{"n":2,"ar":"مِنْ شَرِّ مَا خَلَقَ","tr":"Min syarri maa khalaq","id":"dari kejahatan apa yang Dia ciptakan,","en":"from the evil of what He has created,"},{"n":3,"ar":"وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ","tr":"Wa min syarri ghaasiqin idzaa waqab","id":"dan dari kejahatan malam apabila telah gelap gulita,","en":"and from the evil of darkness when it spreads,"},{"n":4,"ar":"وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ","tr":"Wa min syarrin-naffaatsaati fil-'uqad","id":"dan dari kejahatan (perempuan-perempuan) tukang sihir yang meniup pada buhul-buhul,","en":"and from the evil of those who blow on knots (practicing witchcraft),"},{"n":5,"ar":"وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ","tr":"Wa min syarri haasidin idzaa hasad","id":"dan dari kejahatan orang yang dengki apabila ia dengki.\"","en":"and from the evil of the envier when he envies.\""}]},
{"slug":"al-kautsar","number":108,"name":{"id":"Al-Kautsar","en":"Al-Kautsar"},"arabicName":"الْكَوْثَر","meaning":{"id":"Nikmat yang Banyak","en":"Abundance"},"ayahs":[{"n":1,"ar":"إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ","tr":"Innaa a'taynaakal-kautsar","id":"Sungguh, Kami telah memberimu (Muhammad) nikmat yang banyak.","en":"Indeed, We have granted you (Muhammad) abundance."},{"n":2,"ar":"فَصَلِّ لِرَبِّكَ وَانْحَرْ","tr":"Fasalli lirabbika wanhar","id":"Maka laksanakanlah sholat karena Tuhanmu, dan berkurbanlah (sebagai ibadah dan mendekatkan diri kepada Allah).","en":"So pray to your Lord, and sacrifice."},{"n":3,"ar":"إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ","tr":"Inna syaani-aka huwal-abtar","id":"Sungguh, orang yang membencimu, dialah yang terputus (dari rahmat Allah).","en":"Indeed, your enemy is the one cut off."}]},
{"slug":"al-asr","number":103,"name":{"id":"Al-Asr","en":"Al-Asr"},"arabicName":"الْعَصْر","meaning":{"id":"Masa / Waktu","en":"Time"},"ayahs":[{"n":1,"ar":"وَالْعَصْرِ","tr":"Wal-'ashr","id":"Demi masa,","en":"By Time,"},{"n":2,"ar":"إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ","tr":"Innal-insaana lafii khusr","id":"sungguh, manusia berada dalam kerugian,","en":"indeed, mankind is in loss,"},{"n":3,"ar":"إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ","tr":"Illalladziina aamanuu wa 'amilush-shaalihaati wa tawaashaw bil-haqqi wa tawaashaw bish-shabr","id":"kecuali orang-orang yang beriman dan mengerjakan kebajikan serta saling menasihati untuk kebenaran dan saling menasihati untuk kesabaran.","en":"except those who believe and do righteous deeds, and advise each other to truth, and advise each other to patience."}]},
{"slug":"an-nasr","number":110,"name":{"id":"An-Nasr","en":"An-Nasr"},"arabicName":"النَّصْر","meaning":{"id":"Pertolongan","en":"The Help"},"ayahs":[{"n":1,"ar":"إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ","tr":"Idzaa jaa-a nasrullaahi wal-fath","id":"Apabila telah datang pertolongan Allah dan kemenangan,","en":"When Allah's help and victory come,"},{"n":2,"ar":"وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا","tr":"Wa ra-aytan-naasa yadkhuluuna fii diinillaahi afwaajaa","id":"dan engkau melihat manusia berbondong-bondong masuk agama Allah,","en":"and you see people entering Allah's religion in crowds,"},{"n":3,"ar":"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ ۚ إِنَّهُ كَانَ تَوَّابًا","tr":"Fasabbih bihamdi rabbika wastaghfirh, innahuu kaana tawwaabaa","id":"maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampun kepada-Nya. Sungguh, Dia Maha Penerima tobat.","en":"then glorify the praise of your Lord and seek His forgiveness. Indeed, He is ever Accepting of repentance."}]},
{"slug":"quraisy","number":106,"name":{"id":"Quraisy","en":"Quraysh"},"arabicName":"قُرَيْش","meaning":{"id":"Suku Quraisy","en":"The Tribe of Quraysh"},"ayahs":[{"n":1,"ar":"لِإِيلَافِ قُرَيْشٍ","tr":"Li-iilaafi quraysy","id":"Karena kebiasaan orang-orang Quraisy,","en":"For the familiarity of the Quraysh,"},{"n":2,"ar":"إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ","tr":"Iilaafihim rihlatasy-syitaa-i wash-shayf","id":"(yaitu) kebiasaan mereka bepergian pada musim dingin dan musim panas,","en":"their familiarity with the journey of winter and summer,"},{"n":3,"ar":"فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ","tr":"Falya'buduu rabba haadzal-bayt","id":"maka hendaklah mereka menyembah Tuhan (pemilik) rumah ini (Ka'bah),","en":"let them worship the Lord of this House (the Ka'bah),"},{"n":4,"ar":"الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ","tr":"Alladzii at'amahum min juu'in wa aamanahum min khawf","id":"yang telah memberi makanan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari ketakutan.","en":"who has fed them, saving them from hunger, and secured them from fear."}]},
{"slug":"al-lahab","number":111,"name":{"id":"Al-Lahab","en":"Al-Lahab"},"arabicName":"الْمَسَد","meaning":{"id":"Gejolak Api / Tali Sabut","en":"The Flame / The Palm Fiber"},"ayahs":[{"n":1,"ar":"تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ","tr":"Tabbat yadaa abii lahabin wa tabb","id":"Binasalah kedua tangan Abu Lahab dan benar-benar binasa dia!","en":"May the hands of Abu Lahab be ruined, and ruined is he!"},{"n":2,"ar":"مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ","tr":"Maa aghnaa 'anhu maaluhuu wa maa kasab","id":"Tidak berguna baginya hartanya dan apa yang dia usahakan.","en":"His wealth and whatever he earned will not benefit him."},{"n":3,"ar":"سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ","tr":"Sayaslaa naaran dzaata lahab","id":"Kelak dia akan masuk ke dalam api yang bergejolak (neraka).","en":"He will burn in a blazing fire,"},{"n":4,"ar":"وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ","tr":"Wamra-atuhuu hammaalatal-hatab","id":"Dan (begitu pula) istrinya, pembawa kayu bakar (penyebar fitnah).","en":"and his wife, the carrier of firewood (the spreader of slander),"},{"n":5,"ar":"فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ","tr":"Fii jiidihaa hablum-min masad","id":"Di lehernya ada tali dari sabut yang dipintal.","en":"around her neck a rope of twisted palm fiber."}]},
{"slug":"al-fil","number":105,"name":{"id":"Al-Fil","en":"Al-Fil"},"arabicName":"الْفِيل","meaning":{"id":"Gajah","en":"The Elephant"},"ayahs":[{"n":1,"ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ","tr":"Alam tara kayfa fa'ala rabbuka bi-as-haabil-fiil","id":"Tidakkah engkau (Muhammad) memperhatikan bagaimana Tuhanmu telah bertindak terhadap pasukan bergajah?","en":"Have you not seen how your Lord dealt with the army of the elephant?"},{"n":2,"ar":"أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ","tr":"Alam yaj'al kaydahum fii tadhliil","id":"Bukankah Dia telah menjadikan tipu daya mereka sia-sia?","en":"Did He not bring their plan to nothing?"},{"n":3,"ar":"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","tr":"Wa arsala 'alayhim tayran abaabiil","id":"Dan Dia mengirimkan kepada mereka burung yang berbondong-bondong,","en":"And He sent against them birds in flocks,"},{"n":4,"ar":"تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ","tr":"Tarmiihim bihijaaratim-min sijjiil","id":"yang melempari mereka dengan batu dari tanah liat yang dibakar,","en":"striking them with stones of baked clay,"},{"n":5,"ar":"فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ","tr":"Faja'alahum ka'asfim-ma'kuul","id":"sehingga mereka dijadikan-Nya seperti daun-daun yang dimakan (ulat).","en":"and made them like devoured chaff."}]},
{"slug":"al-kafirun","number":109,"name":{"id":"Al-Kafirun","en":"Al-Kafirun"},"arabicName":"الْكَافِرُون","meaning":{"id":"Orang-orang Kafir","en":"The Disbelievers"},"ayahs":[{"n":1,"ar":"قُلْ يَا أَيُّهَا الْكَافِرُونَ","tr":"Qul yaa ayyuhal-kaafiruun","id":"Katakanlah (Muhammad), \"Wahai orang-orang kafir!\"","en":"Say: \"O disbelievers!\""},{"n":2,"ar":"لَا أَعْبُدُ مَا تَعْبُدُونَ","tr":"Laa a'budu maa ta'buduun","id":"Aku tidak akan menyembah apa yang kamu sembah,","en":"I do not worship what you worship,"},{"n":3,"ar":"وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ","tr":"Wa laa antum 'aabiduuna maa a'bud","id":"dan kamu bukan penyembah apa yang aku sembah,","en":"nor are you worshippers of what I worship,"},{"n":4,"ar":"وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ","tr":"Wa laa ana 'aabidun maa 'abadtum","id":"dan aku tidak pernah menjadi penyembah apa yang kamu sembah,","en":"nor will I worship what you worship,"},{"n":5,"ar":"وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ","tr":"Wa laa antum 'aabiduuna maa a'bud","id":"dan kamu tidak pernah (pula) menjadi penyembah apa yang aku sembah.","en":"nor will you worship what I worship."},{"n":6,"ar":"لَكُمْ دِينُكُمْ وَلِيَ دِينِ","tr":"Lakum diinukum wa liya diin","id":"Untukmu agamamu, dan untukku agamaku.","en":"For you is your religion, and for me is my religion."}]},
{"slug":"al-maun","number":107,"name":{"id":"Al-Maun","en":"Al-Ma'un"},"arabicName":"الْمَاعُون","meaning":{"id":"Barang-barang yang Berguna","en":"Small Kindnesses"},"ayahs":[{"n":1,"ar":"أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ","tr":"Ara-aytalladzii yukadzdzibu bid-diin","id":"Tahukah kamu (orang) yang mendustakan agama?","en":"Do you see the one who denies the religion?"},{"n":2,"ar":"فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ","tr":"Fadzaalikalladzii yadu'-'ul-yatiim","id":"Itulah orang yang menghardik anak yatim,","en":"That is the one who repulses the orphan,"},{"n":3,"ar":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ","tr":"Wa laa yahudh-dhu 'alaa ta'aamil-miskiin","id":"dan tidak mendorong memberi makan orang miskin.","en":"and does not encourage the feeding of the poor."},{"n":4,"ar":"فَوَيْلٌ لِلْمُصَلِّينَ","tr":"Fawaylul-lil-mushalliin","id":"Maka celakalah orang-orang yang sholat,","en":"So woe to those who pray,"},{"n":5,"ar":"الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ","tr":"Alladziina hum 'an shalaatihim saahuun","id":"(yaitu) orang-orang yang lalai terhadap sholatnya,","en":"who are heedless of their prayer,"},{"n":6,"ar":"الَّذِينَ هُمْ يُرَاءُونَ","tr":"Alladziina hum yuraa-uun","id":"yang berbuat riya,","en":"who show off,"},{"n":7,"ar":"وَيَمْنَعُونَ الْمَاعُونَ","tr":"Wa yamna'uunal-maa'uun","id":"dan enggan (memberikan) bantuan.","en":"and refuse small kindnesses."}]},
{"slug":"al-humazah","number":104,"name":{"id":"Al-Humazah","en":"Al-Humazah"},"arabicName":"الْهُمَزَة","meaning":{"id":"Pengumpat","en":"The Slanderer"},"ayahs":[{"n":1,"ar":"وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ","tr":"Waylul-likulli humazatil-lumazah","id":"Celakalah bagi setiap pengumpat dan pencela,","en":"Woe to every slanderer and backbiter,"},{"n":2,"ar":"الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ","tr":"Alladzii jama'a maalan wa 'addadah","id":"yang mengumpulkan harta dan menghitung-hitungnya,","en":"who collects wealth and counts it,"},{"n":3,"ar":"يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ","tr":"Yahsabu anna maalahuu akhladah","id":"dia mengira bahwa hartanya itu dapat mengekalkannya.","en":"thinking his wealth will make him immortal."},{"n":4,"ar":"كَلَّا ۖ لَيُنْبَذَنَّ فِي الْحُطَمَةِ","tr":"Kallaa layunbadzanna fil-hutamah","id":"Sekali-kali tidak! Pasti dia akan dilemparkan ke dalam Huthamah.","en":"By no means! He will surely be cast into the Crusher."},{"n":5,"ar":"وَمَا أَدْرَاكَ مَا الْحُطَمَةُ","tr":"Wa maa adraaka mal-hutamah","id":"Dan tahukah engkau apa Huthamah itu?","en":"And what will make you know what the Crusher is?"},{"n":6,"ar":"نَارُ اللَّهِ الْمُوقَدَةُ","tr":"Naarullaahil-muuqadah","id":"(Yaitu) api (azab) Allah yang dinyalakan,","en":"It is the kindled fire of Allah,"},{"n":7,"ar":"الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ","tr":"Allatii tat-tali'u 'alal-af-idah","id":"yang (membakar) sampai ke hati.","en":"which mounts up to the hearts."},{"n":8,"ar":"إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ","tr":"Innahaa 'alayhim mu'shadah","id":"Sungguh, api itu ditutup rapat atas mereka,","en":"Indeed, it will be closed down upon them,"},{"n":9,"ar":"فِي عَمَدٍ مُمَدَّدَةٍ","tr":"Fii 'amadim-mumaddadah","id":"(sedang mereka itu) diikat pada tiang-tiang yang panjang.","en":"in extended columns."}]},
{"slug":"at-takatsur","number":102,"name":{"id":"At-Takatsur","en":"At-Takathur"},"arabicName":"التَّكَاثُر","meaning":{"id":"Bermegah-Megahan","en":"Rivalry in Worldly Increase"},"ayahs":[{"n":1,"ar":"أَلْهَاكُمُ التَّكَاثُرُ","tr":"Alhaakumut-takaatsur","id":"Bermegah-megahan telah melalaikan kamu,","en":"Competition for more has distracted you,"},{"n":2,"ar":"حَتَّىٰ زُرْتُمُ الْمَقَابِرَ","tr":"Hattaa zurtumul-maqaabir","id":"sampai kamu masuk ke dalam kubur.","en":"until you visit the graves."},{"n":3,"ar":"كَلَّا سَوْفَ تَعْلَمُونَ","tr":"Kallaa sawfa ta'lamuun","id":"Sekali-kali tidak! Kelak kamu akan mengetahui (akibat perbuatanmu itu),","en":"No! You will come to know."},{"n":4,"ar":"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","tr":"Tsumma kallaa sawfa ta'lamuun","id":"kemudian sekali-kali tidak! Kelak kamu akan mengetahui.","en":"Then no! You will come to know."},{"n":5,"ar":"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ","tr":"Kallaa law ta'lamuuna 'ilmal-yaqiin","id":"Sekali-kali tidak! Sekiranya kamu mengetahui dengan pasti,","en":"No! If only you knew with certainty,"},{"n":6,"ar":"لَتَرَوُنَّ الْجَحِيمَ","tr":"Latarawunnal-jahiim","id":"niscaya kamu benar-benar akan melihat neraka Jahim.","en":"you would surely see the Hellfire."},{"n":7,"ar":"ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ","tr":"Tsumma latarawunnahaa 'aynal-yaqiin","id":"Kemudian kamu benar-benar akan melihatnya dengan mata kepala sendiri,","en":"Then you would see it with the eye of certainty."},{"n":8,"ar":"ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ","tr":"Tsumma latus-alunna yawma-idzin 'anin-na'iim","id":"kemudian kamu benar-benar akan ditanya pada hari itu tentang kenikmatan (yang megah di dunia itu).","en":"Then you will surely be asked that day about pleasure."}]},
{"slug":"al-qariah","number":101,"name":{"id":"Al-Qariah","en":"Al-Qari'ah"},"arabicName":"الْقَارِعَة","meaning":{"id":"Hari Kiamat","en":"The Striking Calamity"},"ayahs":[{"n":1,"ar":"الْقَارِعَةُ","tr":"Al-qaari'ah","id":"Hari Kiamat,","en":"The Striking Calamity!"},{"n":2,"ar":"مَا الْقَارِعَةُ","tr":"Mal-qaari'ah","id":"apakah hari Kiamat itu?","en":"What is the Striking Calamity?"},{"n":3,"ar":"وَمَا أَدْرَاكَ مَا الْقَارِعَةُ","tr":"Wa maa adraaka mal-qaari'ah","id":"Dan tahukah kamu apakah hari Kiamat itu?","en":"And what will make you know what the Striking Calamity is?"},{"n":4,"ar":"يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ","tr":"Yawma yakuunun-naasu kal-faraasyil-mabtsuuts","id":"Pada hari itu manusia seperti laron yang berterbangan,","en":"The Day when people will be like scattered moths,"},{"n":5,"ar":"وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ","tr":"Wa takuunul-jibaalu kal-'ihnil-manfuusy","id":"dan gunung-gunung seperti bulu yang dihambur-hamburkan.","en":"and the mountains will be like fluffed wool."},{"n":6,"ar":"فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ","tr":"Fa-ammaa man tsaqulat mawaaziinuh","id":"Maka adapun orang yang berat timbangan (kebaikan)nya,","en":"Then as for one whose scales are heavy (with good),"},{"n":7,"ar":"فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ","tr":"Fahuwa fii 'iisyatir-raadhiyah","id":"maka dia berada dalam kehidupan yang memuaskan (senang),","en":"he will be in a pleasing life."},{"n":8,"ar":"وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ","tr":"Wa ammaa man khaffat mawaaziinuh","id":"Dan adapun orang yang ringan timbangan (kebaikan)nya,","en":"But as for one whose scales are light,"},{"n":9,"ar":"فَأُمُّهُ هَاوِيَةٌ","tr":"Fa-ummuhuu haawiyah","id":"maka tempat kembalinya adalah Hawiyah (neraka).","en":"his refuge will be an abyss."},{"n":10,"ar":"وَمَا أَدْرَاكَ مَا هِيَهْ","tr":"Wa maa adraaka maa hiyah","id":"Dan tahukah kamu apakah neraka Hawiyah itu?","en":"And what will make you know what it is?"},{"n":11,"ar":"نَارٌ حَامِيَةٌ","tr":"Naarun haamiyah","id":"(Yaitu) api yang sangat panas.","en":"A fire intensely hot."}]}];
